INSERT INTO public.content (key,value,updated_at) VALUES ('home_slides','[{"id":"hero-documentary","tag":"Documentary Films & Photography","headline":"The Truth, In Motion.","subheadline":"We go where the story lives. Cinematic filmmaking and raw photojournalism that capture the unfiltered pulse of East Africa, told with dignity, depth, and a proximity that defies distance.","buttonLabel":"Experience the Work","buttonTo":"/portfolio"},{"id":"hero-events","tag":"Live Event Coverage & Broadcasting","headline":"Capturing the Now.","subheadline":"When the room goes live, there are no second takes. Flawless multicamera broadcast engineering that turns high stakes summits and cultural milestones into borderless global experiences.","buttonLabel":"See Our Setup","buttonTo":"/services","image":"storage:home/hero-events-6a804cca-efc6-499f-8a4b-2703bd8cb75f.jpg"},{"id":"hero-branding","tag":"Brand Design & Visual Identity","headline":"Visuals That Speak Volumes.","subheadline":"A brand is more than a logo; it is a legacy. We craft striking visual identities and bold design systems that command attention and anchor your institutional authority.","buttonLabel":"View Brand Systems","buttonTo":"/portfolio","image":"storage:home/hero-branding-c5da7ea4-2cd6-48a6-89f0-65b5d2373207.jpg"},{"id":"hero-digital","tag":"Digital Marketing & Campaigns","headline":"Igniting Digital Movements.","subheadline":"We do not just add to the noise; we cut right through it. Precision campaigns and highly targeted digital strategies designed to spark conversations, move audiences, and deliver undeniable impact.","buttonLabel":"Amplify Your Reach","buttonTo":"/services","image":"storage:home/hero-digital-e95e3765-b6c5-4e34-9bba-2ef1953eb618.jpg"},{"id":"hero-communications","tag":"Strategic Communications & Creative Direction","headline":"Shaping the Narrative.","subheadline":"Complex missions require visionary translation. We provide the creative compass and strategic messaging to bridge the gap between your highest ambitions and the public imagination.","buttonLabel":"Start the Conversation","buttonTo":"/contact","image":"storage:home/hero-communications-07e5a8b0-3e29-498e-bc21-73def02bc015.jpg"}]','2026-10-26T08:16:34.296+00:00') ON CONFLICT DO NOTHING;
