INSERT INTO public.content (key,value,updated_at) VALUES ('home_intro','We are Origin 13, a communications team based in Ethiopia. We make films, photographs, designs and campaigns that help you share your work with the people you want to reach.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
