INSERT INTO public.content (key,value,updated_at) VALUES ('about_intro','We are a communications team based in Addis Ababa. We make films, take photographs, cover events and help organizations with design and campaigns.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('about_story','For more than 12 years our team has worked across Ethiopia, Kenya, Somalia, Djibouti and South Sudan — in laboratories, rural communities, courtrooms and highland farms.
