INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-kit_blurb','Logo, colors and stationery concept.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-challenge_title','Abbro — Making online shopping feel safe.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-challenge_blurb','For many shoppers in Addis Ababa, buying online still feels uncertain. Abbro needed an identity that felt modern and energetic enough to stand out on a phone screen, yet warm and dependable enough to earn first-time trust.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-solution_title','Abbro — Two people, one connection.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-solution_blurb','The symbol shows two figures joined by a single line — a buyer and a seller, linked. Set inside a rounded yellow square, it reads clearly as an app icon. A friendly, rounded lowercase wordmark keeps the brand approachable and easy to say.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-palette_title','Abbro — A colour that means “go”.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-palette_blurb','A bright signal yellow carries the brand’s optimism and is used for anything that invites action. Deep black brings confidence and clarity, while white and kraft keep the system calm and practical across screens and packaging.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-type_title','Abbro — Bold, rounded, friendly.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-type_blurb','Abbro is a custom typeface drawn for the brand: heavy, even strokes, soft circular bowls and rounded lowercase shapes that feel friendly and confident. Made only for Abbro, it gives the name a voice no other shop can borrow, and stays legible from an app icon to the side of a van.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-pattern_title','Abbro — A network of connections.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-pattern_blurb','The connecting line from the symbol extends into a network pattern of dots and links — every node a person, every line a delivery. It wraps tissue paper, mailers and social posts, so the idea of “together” travels with every order.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-1_title','Abbro — Packaging','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-brd-1_blurb','Delivery packaging concept.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
