INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-macha-kit_title','Macha Studios — Brand Kit','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-macha-kit_blurb','Logo, colors and stationery concept.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-macha-challenge_title','Macha Studios — Quiet in a loud market.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-macha-challenge_blurb','Wedding photography is crowded with ornate, glossy branding. Macha needed to feel premium and editorial without decoration — a brand that steps back, so the couple’s real moments can lead.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-macha-solution_title','Macha Studios — The frame as a promise.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-macha-solution_blurb','The symbol is a single open frame with one softened corner — a viewfinder, a photograph and an album at once. The gap in the line stands for moments that are never staged. Clean capitals give the wordmark a calm, timeless confidence.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-macha-palette_title','Macha Studios — Ivory and charcoal.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-macha-palette_blurb','A restrained palette of warm ivory and deep charcoal recalls fine-art paper and darkroom prints. Soft linen and a muted stone grey add texture, letting the photographs bring all the colour.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-macha-type_title','Macha Studios — Editorial and calm.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
