INSERT INTO public.content (key,value,updated_at) VALUES ('portfolio_work_w-macha-type_blurb','Montserrat in spaced capitals gives headings the feel of a gallery title card, while its lighter weights keep captions, letters and invoices quiet and elegant.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
