INSERT INTO public.content (key,value,updated_at) VALUES ('featured_gfn-seedlings_title','Misting the Highland Seedlings','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_gfn-seedlings_subtitle','Nursery propagation and community food security','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_gfn-seedlings_location','Highland Greenhouses, Ethiopia','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_gfn-seedlings_partner','Global Food Banking Network','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_gfn-seedlings_category','stills','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_gfn-seedlings_image','/assets/hosted/slide-1.jpg','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_gfn-seedlings_synopsis','Inside community-managed highland greenhouses, a worker sprays a fine mist across nursery beds as others carry trays of young seedlings. Origin 13 documented this vital chain of food security and smallholder climate resilience for the Global Food Banking Network.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_gfn-seedlings_fieldNotes','Captured on prime cinema optics in morning mist and diffused skylight. No staging — only the quiet cadence of agricultural stewardship.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_gfn-seedlings_quote','Food sovereignty begins in the quiet dedication of the nursery. Honoring the people who nurture life from soil requires unhurried observation.','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_africa-cdc-lab_title','The Cold Chain Sentinel','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_africa-cdc-lab_subtitle','Continental genomic surveillance and African scientific leadership','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.content (key,value,updated_at) VALUES ('featured_africa-cdc-lab_location','Addis Ababa, Ethiopia','2026-10-26T12:35:46.106+00:00') ON CONFLICT DO NOTHING;
