INSERT INTO public.content (key,value,updated_at) VALUES ('featured_africa-cdc-lab_synopsis','Inside the laboratories powering continental disease surveillance, African scientists and technicians maintain the standards that protect millions. A film that shifts the narrative from vulnerability to leadership.','2026-10-26T12:35:46.107+00:00') ON CONFLICT DO NOTHING;
